    def __init__(self): self.calls=[]
    def charge(self, amount, key=None):
        self.calls.append((amount,key)); return "p1"
class Store:
    def __init__(self): self.paid={}
    def save(self, key, payment): self.paid[key]=payment
class PaymentTests(unittest.TestCase):
